import { GRID } from '../game/GameConfig.js';
import { GOLEM_TYPES } from '../data/golems.js';
import { getElementalModifierFor } from './elementalAffinity.js';
import { WEAPON_TYPES } from '../data/items.js';

/**
 * GolemCompanion — summoned at the REST Combine Station (ingredient + Mana,
 * see CraftingSystem.claimCraftedGolem). One data-driven class parameterized
 * by GOLEM_TYPES[type] rather than four subclasses, matching the Enemy
 * "compose, don't subclass" convention (GLOSSARY.md's Enemy entry) even
 * though golems aren't Enemies.
 *
 * State machine (deliberately simpler than NPCRat — no flee/permaFlee; the
 * inbox description is "basic melee attacks" with no retreat behavior):
 *   'idle'   — no target; drifts toward player to stay close
 *   'chase'  — pursuing a hostile enemy, closes to attack range
 *   'windup' — in range, telegraphing a strike (bug-inbox: golems attacked
 *              instantly with no tell); holds position, target frozen, damage
 *              lands when windupTimer expires — same shape as Enemy's own
 *              windup/attack split (WindupTelegraphMechanic), scaled down to
 *              one flat duration since golems don't carry per-weapon timing.
 *   'dead'   — Mud Golem only: body destroyed, resurrectTimer counting down
 *              to an indefinite revive (see GOLEM_TYPES.mud.resurrectCooldown).
 *              Every other type is simply removed from game.golems on death —
 *              see CompanionSystem.updateGolems.
 *
 * Render char is a single printable-ASCII glyph shared by all golem types
 * (per CLAUDE.md's "printable ASCII for enemies/background objects"
 * convention — distinct from the Unicode-symbol rule that governs the
 * recipe-result sentinel chars in items.js); types are told apart by color.
 * equipWeapon() (feature-inbox: ground-weapon pickup) overrides the char to
 * the equipped weapon's glyph once armed — color still carries golem type.
 */

const RENDER_CHAR = 'g';

const INVULNERABILITY_DURATION = 0.5;

// bug-inbox: golems were "much too fast, should not move much faster when
// aggro" — chase speed dropped 90 → 70 and the idle→chase ratio narrowed
// (0.6x → 0.75x) so aggro reads as a lean into the chase, not a burst.
const SPEED = 70;
const ATTACK_RANGE = GRID.CELL_SIZE * 1.75;
const ATTACK_COOLDOWN = 1.4;
const ATTACK_WINDUP = 0.35;
const ATTACK_DAMAGE = 1;
const AGGRO_RANGE = GRID.CELL_SIZE * 9;

// feature-inbox: "golems should equip weapons found on the ground" —
// simplified subset (no inventory, no preferred-item list, no use-cooldown;
// see Enemy.js's itemUsage/evaluateItemPickup for the fuller system this
// deliberately does not port). A golem only benefits from MELEE weapons
// since its attack is a fixed-range windup/strike with no ranged branch.
const WEAPON_PICKUP_RANGE = GRID.CELL_SIZE * 3;

const FOLLOW_RADIUS = GRID.CELL_SIZE * 3;
const FOLLOW_SPEED_MULT = 0.75;

export class GolemCompanion {
  constructor(type, x, y) {
    this.golemType = type;
    const def = GOLEM_TYPES[type];
    this.def = def;

    this.position = { x, y };
    this.velocity = { vx: 0, vy: 0 };
    this.targetVelocity = { vx: 0, vy: 0 };

    this.char = RENDER_CHAR;
    this.color = def.color;
    this.baseColor = def.color;
    this.width = GRID.CELL_SIZE;
    this.height = GRID.CELL_SIZE;
    this.plane = 0;

    this.maxHp = def.maxHp;
    this.hp = def.maxHp;
    this.invulnerabilityTimer = 0;
    this.attackTimer = 0;

    // Instance-level combat stats, defaulted from the flat golem baseline —
    // overwritten by equipWeapon() when a better ground weapon is found.
    // Every golem type starts identical here; GOLEM_TYPES carries no
    // per-type damage/range (see class comment).
    this.attackDamage = ATTACK_DAMAGE;
    this.attackRange = ATTACK_RANGE;
    this.equippedWeaponChar = null;

    this.state = 'idle';
    this.target = null;
    this.windupTimer = 0;
    this.windupDuration = ATTACK_WINDUP;

    // Mud Golem only — see class comment.
    this.resurrectTimer = 0;

    // Physics flags so PhysicsSystem treats us like a normal collide-able mover.
    this.hasCollision = true;
    this.boundToGrid = true;
    this.isSmall = false;
    this.collisionMap = null;
    this.backgroundObjects = null; // layer-guard-ok: router-injected

    // Render-path compatibility: drawNonSappingEnemies-style consumers check these.
    this.sapping = false;
    this.isBossEntity = false;
    this.isDying = false;
    this.dead = false;
    this.data = { float: false };

    // Wired by game on creation / room entry.
    this.game = null;
    this.room = null;
  }

  setGame(game) { this.game = game; }
  setRoom(room) { this.room = room; }
  setCollisionMap(collisionMap) { this.collisionMap = collisionMap; }
  setBackgroundObjects(backgroundObjects) { this.backgroundObjects = backgroundObjects; } // layer-guard-ok

  // Shared companion hook: snap to a radial slot around the player and reset
  // per-room combat state. Mirrors NPCRat.onRoomEnter so main.js can dispatch
  // all companions through one unified call site. A golem mid-resurrect keeps
  // counting down through the room change rather than resetting — only the
  // dead body is instant to lose, not the wait to get it back.
  onRoomEnter(player, game, slot = 0, total = 1) {
    if (!player) return;
    const angle = (slot / Math.max(total, 1)) * Math.PI * 2;
    const radius = GRID.CELL_SIZE * 1.1;
    this.position.x = player.position.x + Math.cos(angle) * radius;
    this.position.y = player.position.y + Math.sin(angle) * radius;
    this.velocity.vx = 0;
    this.velocity.vy = 0;
    this.targetVelocity.vx = 0;
    this.targetVelocity.vy = 0;
    this.invulnerabilityTimer = 0;
    this.attackTimer = 0;
    this.windupTimer = 0;
    if (this.state !== 'dead') {
      this.hp = this.maxHp;
      this.state = 'idle';
    }
    this.target = null;
    if (game) {
      this.game = game;
      this.room = game.currentRoom;
      this.collisionMap = game.currentRoom?.collisionMap || null;
      this.backgroundObjects = game._activeBackgroundObjects() || null; // layer-guard-ok: routed read
    }
  }

  // Per-frame driver. main.js passes the live hostile-enemies array, the
  // player, and the sibling golem roster (for separation).
  // Returns { revived: true } when a Mud Golem's cooldown finishes this frame
  // so CompanionSystem can fire feedback (particles/message/SFX).
  update(deltaTime, enemies, player, siblings = null) {
    if (this.state === 'dead') {
      this.resurrectTimer -= deltaTime;
      if (this.resurrectTimer <= 0) {
        this.hp = this.maxHp;
        this.state = 'idle';
        this.target = null;
        if (player) {
          this.position.x = player.position.x + (Math.random() - 0.5) * GRID.CELL_SIZE * 2;
          this.position.y = player.position.y + (Math.random() - 0.5) * GRID.CELL_SIZE * 2;
        }
        return { revived: true };
      }
      return null;
    }

    if (this.invulnerabilityTimer > 0) {
      this.invulnerabilityTimer -= deltaTime;
      if (this.invulnerabilityTimer < 0) this.invulnerabilityTimer = 0;
    }
    if (this.attackTimer > 0) this.attackTimer -= deltaTime;

    // Environmental reactions (bug-inbox #10, "targeted subset now" scope) —
    // checked every non-dead frame regardless of combat state, since a golem
    // can wander into water/lava with no target at all.
    const envResult = this._checkEnvironmentalReaction();
    if (envResult) return envResult;

    if (this.def.regen && this.hp < this.maxHp) {
      this.hp = Math.min(this.maxHp, this.hp + this.def.regen * deltaTime);
    }

    // Target is frozen through a windup — re-picking mid-swing would let the
    // golem retarget onto something closer without ever finishing the tell.
    if (this.state !== 'windup') {
      this.target = this._findNearestEnemy(enemies);
    } else if (!this.target || this.target.hp <= 0 || this.target.isDying) {
      this.windupTimer = 0;
      this.target = null;
    }

    let result = null;
    if (this.target) {
      if (this.state === 'windup') {
        result = this._continueWindup(deltaTime);
      } else {
        this.state = 'chase';
        result = this._chaseAndAttack(deltaTime);
      }
    } else {
      this.state = 'idle';
      this._driftTowardPlayer(deltaTime, player);
    }
    this._applySeparation(siblings);
    return result;
  }

  // Render-path compatibility shim, mirrors Enemy's WindupTelegraphMechanic
  // surface so ExploreRenderer-style consumers can read a golem's windup the
  // same way they read an enemy's: guaranteed-white in the back half, plain
  // red '!' the rest of the way (golems carry no equipped weapon to show).
  isWindingUp() { return this.state === 'windup' && this.windupTimer > 0; }

  getWindupFlashColor() {
    if (!this.isWindingUp()) return null;
    return this.windupTimer <= this.windupDuration / 2 ? '#ffffff' : null;
  }

  getWindupIndicator() {
    if (!this.isWindingUp()) return null;
    return { char: '!', color: '#ff0000', offsetY: -GRID.CELL_SIZE };
  }

  // Boids-style separation — same shape as NPCRat._applySeparation.
  _applySeparation(siblings) {
    if (!siblings || siblings.length < 2) return;
    const RADIUS = GRID.CELL_SIZE * 0.9;
    const RADIUS_SQ = RADIUS * RADIUS;
    const STRENGTH = SPEED * 0.7;
    let pushX = 0;
    let pushY = 0;
    let count = 0;
    for (const other of siblings) {
      if (!other || other === this || other.state === 'dead') continue;
      const dx = this.position.x - other.position.x;
      const dy = this.position.y - other.position.y;
      const dSq = dx * dx + dy * dy;
      if (dSq > 0 && dSq < RADIUS_SQ) {
        const d = Math.sqrt(dSq);
        const w = (RADIUS - d) / RADIUS;
        pushX += (dx / d) * w;
        pushY += (dy / d) * w;
        count++;
      }
    }
    if (count > 0) {
      this.velocity.vx += pushX * STRENGTH;
      this.velocity.vy += pushY * STRENGTH;
      this.targetVelocity.vx = this.velocity.vx;
      this.targetVelocity.vy = this.velocity.vy;
    }
  }

  // Damage handler. No flee behavior — golems stand and fight until hp runs
  // out. On death: Mud Golem drops into 'dead' (resurrect countdown starts);
  // every other type signals { died: true } so CompanionSystem removes it
  // from game.golems.
  //
  // `onHit` (bug-inbox #10, "targeted subset now" scope) is the same effect
  // key Enemy attacks already carry (e.g. 'burn') — reuses
  // elementalAffinity.js as-is rather than porting full status-effect
  // parity. A type with no affinities/elementalAffinity entry is unaffected
  // (getElementalModifierFor returns 1.0).
  takeDamage(amount, attacker = null, onHit = null) {
    if (this.invulnerabilityTimer > 0) return false;
    if (this.state === 'dead') return false;
    if (onHit) {
      const modifier = getElementalModifierFor(this.def.elementalAffinity, this.def.affinities, onHit);
      amount = Math.max(0, Math.round(amount * modifier));
    }
    this.hp -= amount;
    this.invulnerabilityTimer = INVULNERABILITY_DURATION;
    this.game?.audioSystem?.playSFX?.('enemy_hit');
    if (this.hp <= 0) {
      this.hp = 0;
      if (this.def.resurrect) {
        this.state = 'dead';
        this.resurrectTimer = this.def.resurrectCooldown;
        this.target = null;
        return { damaged: true, died: true, resurrecting: true };
      }
      return { damaged: true, died: true };
    }
    return { damaged: true };
  }

  // Render-path compatibility shims.
  shouldRenderVisible() { return this.state !== 'dead'; }

  getIframeFlashColor() {
    if (this.invulnerabilityTimer <= 0) return null;
    const blinkCycle = Math.floor(this.invulnerabilityTimer / 0.08);
    return blinkCycle % 2 === 0 ? '#ffffff' : null;
  }

  getDOTBlinkColor() { return null; }
  getStatusPipRows() { return []; }

  // ─── Internals ──────────────────────────────────────────────────────────

  _findNearestEnemy(enemies) {
    if (!enemies || enemies.length === 0) return null;
    let best = null;
    let bestDistSq = AGGRO_RANGE * AGGRO_RANGE;
    for (const e of enemies) {
      if (!e || e === this) continue;
      if (e.tamed) continue;
      if (e.hp <= 0 || e.isDying) continue;
      if ((e.plane ?? 0) !== this.plane) continue;
      const dx = e.position.x - this.position.x;
      const dy = e.position.y - this.position.y;
      const d = dx * dx + dy * dy;
      if (d < bestDistSq) { bestDistSq = d; best = e; }
    }
    return best;
  }

  _chaseAndAttack(deltaTime) {
    const t = this.target;
    const dx = t.position.x - this.position.x;
    const dy = t.position.y - this.position.y;
    const dist = Math.hypot(dx, dy) || 1;
    const dirX = dx / dist;
    const dirY = dy / dist;

    if (dist > this.attackRange) {
      this.targetVelocity.vx = dirX * SPEED;
      this.targetVelocity.vy = dirY * SPEED;
    } else {
      this.targetVelocity.vx = 0;
      this.targetVelocity.vy = 0;
      if (this.attackTimer <= 0 && typeof t.takeDamage === 'function') {
        this.state = 'windup';
        this.windupTimer = ATTACK_WINDUP;
        this.windupDuration = ATTACK_WINDUP;
      }
    }
    this.velocity.vx = this.targetVelocity.vx;
    this.velocity.vy = this.targetVelocity.vy;
    return null;
  }

  // Holds position while the windup telegraph counts down, then lands the
  // hit — mirrors createAttack()/resolveEnemyAttack's windup→strike split on
  // Enemy, collapsed to one step since the golem swing has no travelling
  // hitbox of its own. A target that steps back out of range during the
  // windup simply avoids the swing (no damage), same as dodging any other
  // telegraphed attack; the cooldown still starts so the golem can't retry instantly.
  _continueWindup(deltaTime) {
    this.velocity.vx = 0;
    this.velocity.vy = 0;
    this.targetVelocity.vx = 0;
    this.targetVelocity.vy = 0;
    this.windupTimer -= deltaTime;
    if (this.windupTimer > 0) return null;
    this.windupTimer = 0;
    this.state = 'chase';
    this.attackTimer = ATTACK_COOLDOWN;
    const t = this.target;
    const dist = Math.hypot(t.position.x - this.position.x, t.position.y - this.position.y);
    if (dist <= this.attackRange && typeof t.takeDamage === 'function') {
      t.takeDamage(this.attackDamage);
      // Magma Golem: "can burn enemies" (bug-inbox #10, user-specified design).
      if (this.def.burnOnHit) t.applyStatusEffect?.('burn', this.def.burnOnHit);
      return { attacked: t, damage: this.attackDamage };
    }
    return null;
  }

  // ─── Weapon pickup (feature-inbox, simplified subset) ──────────────────

  // Same one-line comparator as Enemy._weaponPower — melee-only here since
  // the golem has no ranged attack branch to hand a gun/bow/wand to.
  _weaponPower(item) {
    if (!item || item.data?.type !== 'WEAPON' || item.data.weaponType !== WEAPON_TYPES.MELEE) return -1;
    return item.data.damage ?? 0;
  }

  // Scans a ground-item array (game.items) for the strongest melee weapon
  // within WEAPON_PICKUP_RANGE that beats this golem's current damage.
  // Read-only — caller (CompanionSystem.updateGolems) owns removing the
  // winning item from game.items/physicsSystem, mirroring how Enemy.js
  // leaves that removal to its own call site.
  findBetterGroundWeapon(items) {
    if (!items || items.length === 0) return null;
    const currentPower = this.attackDamage;
    let best = null;
    let bestPower = currentPower;
    for (const item of items) {
      if (!item || item.consumed) continue;
      if ((item.plane ?? 0) !== this.plane) continue;
      const power = this._weaponPower(item);
      if (power <= bestPower) continue;
      const dx = item.position.x - this.position.x;
      const dy = item.position.y - this.position.y;
      if (dx * dx + dy * dy > WEAPON_PICKUP_RANGE * WEAPON_PICKUP_RANGE) continue;
      best = item;
      bestPower = power;
    }
    return best;
  }

  // Simplified "equip": bump damage/range to the weapon's stats and swap
  // the render char to it, so a weapon-carrying golem reads differently at
  // a glance — no inventory slot, no use-cooldown, no unequip.
  equipWeapon(item) {
    this.attackDamage = item.data.damage ?? this.attackDamage;
    // Not every melee entry carries `range` (resolveWeaponDefaults only
    // fills it via SUBTYPE_DEFAULTS for some subtypes) — keep the current
    // reach rather than collapsing it to 0 when the field is absent.
    this.attackRange = item.data.range ?? this.attackRange;
    this.equippedWeaponChar = item.char;
    this.char = item.char;
  }

  // bug-inbox #10: "Mud golems should be destroyed by water and lava. Magma
  // golems ... should turn into rock golems when touching water." Checked
  // every frame the golem is alive. Mirrors Enemy._isOnWater()'s
  // backgroundObjects/grid-cell check, extended with an isLava() variant.
  // Returns a death-shaped result (same as takeDamage's die branch) when the
  // reaction kills the golem this frame, else null.
  _checkEnvironmentalReaction() {
    if (this.def.destroyedByWaterAndLava && (this._isOnWater() || this._isOnLava())) {
      this.hp = 0;
      this.invulnerabilityTimer = 0;
      if (this.def.resurrect) {
        this.state = 'dead';
        this.resurrectTimer = this.def.resurrectCooldown;
        this.target = null;
        return { damaged: true, died: true, resurrecting: true };
      }
      return { damaged: true, died: true };
    }
    if (this.def.convertsToRockInWater && this._isOnWater()) {
      this._convertToRockGolem();
    }
    return null;
  }

  _isOnWater() {
    if (!this.backgroundObjects) return false; // layer-guard-ok
    const ex = Math.floor(this.position.x / GRID.CELL_SIZE);
    const ey = Math.floor(this.position.y / GRID.CELL_SIZE);
    for (const obj of this.backgroundObjects) { // layer-guard-ok
      if (!obj.isWater || !obj.isWater()) continue;
      if (Math.floor(obj.position.x / GRID.CELL_SIZE) === ex &&
          Math.floor(obj.position.y / GRID.CELL_SIZE) === ey) {
        return true;
      }
    }
    return false;
  }

  _isOnLava() {
    if (!this.backgroundObjects) return false; // layer-guard-ok
    const ex = Math.floor(this.position.x / GRID.CELL_SIZE);
    const ey = Math.floor(this.position.y / GRID.CELL_SIZE);
    for (const obj of this.backgroundObjects) { // layer-guard-ok
      if (!obj.isLava || !obj.isLava()) continue;
      if (Math.floor(obj.position.x / GRID.CELL_SIZE) === ex &&
          Math.floor(obj.position.y / GRID.CELL_SIZE) === ey) {
        return true;
      }
    }
    return false;
  }

  // Magma Golem quenching to Rock Golem — mutates type/def/hp in place
  // (never removed from game.golems, unlike a death) since this is a
  // transformation, not a kill.
  _convertToRockGolem() {
    const rockDef = GOLEM_TYPES.rock;
    this.golemType = 'rock';
    this.def = rockDef;
    this.color = rockDef.color;
    this.baseColor = rockDef.color;
    this.maxHp = rockDef.maxHp;
    this.hp = Math.min(this.hp, rockDef.maxHp) || rockDef.maxHp;
    this.game?.audioSystem?.playSFX?.('enemy_hit');
  }

  _driftTowardPlayer(deltaTime, player) {
    if (!player) {
      this.velocity.vx = 0;
      this.velocity.vy = 0;
      this.targetVelocity.vx = 0;
      this.targetVelocity.vy = 0;
      return;
    }
    const dx = player.position.x - this.position.x;
    const dy = player.position.y - this.position.y;
    const d = Math.hypot(dx, dy);
    if (d > FOLLOW_RADIUS) {
      const s = SPEED * FOLLOW_SPEED_MULT;
      this.targetVelocity.vx = (dx / d) * s;
      this.targetVelocity.vy = (dy / d) * s;
    } else {
      this.targetVelocity.vx = 0;
      this.targetVelocity.vy = 0;
    }
    this.velocity.vx = this.targetVelocity.vx;
    this.velocity.vy = this.targetVelocity.vy;
  }
}
