import { Item } from '../entities/Item.js';
import { BackgroundObject } from '../entities/BackgroundObject.js';
import { Leshy } from '../entities/Leshy.js';
import { Fairy } from '../entities/Fairy.js';
import { isIngredient, isItem, generateEnemyDrops } from '../data/items.js';
import { pickQuagmireIngredient } from '../data/alchemy.js';
import { getZoneRandomEnemy, ENEMIES } from '../data/enemies.js';
import { ZONE_MINERALS } from '../data/zones.js';
import { CHARACTER_TYPES } from '../data/characters.js';
import { createDebris } from '../entities/Debris.js';
import { createIceBurst, Particle } from '../entities/Particle.js';
import { INTERACTION_RANGE, OBJECT_ANIMATIONS, GRID, GAME_STATES } from '../game/GameConfig.js';
import { inSamePlane, planeOf, objectOnPlane, tagInteriorPlane } from './PlaneSystem.js';
import { WiseFellow } from '../entities/WiseFellow.js';

// Refusal singletons for resolveSmashRefusal — the melee loop tests every
// object a swing overlaps, so a refusal is not worth an allocation.
const SMASH_REFUSED = Object.freeze({ fireBypass: false });
const SMASH_REFUSED_UNLESS_BURNED = Object.freeze({ fireBypass: true });

// Reach for the armed-Bottle fairy catch (InteractionSystem.tryBottleFairy).
// Wider than AlchemySystem's one-cell liquid radius: a liquid tile sits still
// and a fluttering fairy does not, so the catch gets a cell and a half.
const FAIRY_CATCH_RADIUS = GRID.CELL_SIZE * 1.5;

export class InteractionSystem {
  constructor(game) {
    this.game = game;
    this._lavaWaterCheckTimer = 0;
  }

  // SPACE in REST with nothing nearby to interact with — expanding fade-out
  // ring at the player as feedback. Tracks the player's live position (see
  // RestRenderer), so no position is captured here. Decayed/removed in
  // WorldEffectsSystem.
  spawnIdleEcho() {
    this.game.idleEchoes.push({ age: 0 });
  }

  // Each zone's rocks hide a different mineral (rock-harvest rare slot and the
  // once-per-rock poke drop). Red owns Metal; yellow is the gem/magic zone;
  // cyan feeds the bow path. Unlisted zones (gray, blue) hide nothing extra.
  getZoneMineral(zone) {
    const minerals = ZONE_MINERALS[zone];
    if (!minerals?.length) return null;
    // Single-mineral zones return their one entry; yellow rolls among its gems.
    return minerals[Math.floor(Math.random() * minerals.length)];
  }

  // Melee-vs-background-object damage for CombatSystem's generic object-smash
  // path. Bushes always die in one hit to a blunt or axe strike. Cuttable
  // growth (grass) is choosy about its cutters: axes deal half damage
  // against it — they're blades, but clumsy ones for trimming; true blades
  // (sword, scythe, spear, dagger — isBlade) never call this for cuttable
  // objects at all, since CombatSystem routes them to an instant cutGrass()
  // cut in BackgroundObject.takeDamage regardless of the damage number;
  // hammers thump it for zero — a smashing tool has no business trimming or
  // flattening a blade of grass, so it just rustles (chaff VFX still fires
  // in CombatSystem) and leaves the grass standing. Everything else deals
  // its normal damage against grass; hammers (canSmash) still double their
  // damage against every other object.
  resolveSmashDamage(attack, obj) {
    if (obj.char === '%' && (attack.isBlunt || attack.weaponSubtype === 'axe')) {
      return obj.hp;
    }
    if (obj.data.cuttable) {
      if (attack.weaponSubtype === 'hammer') return 0;
      if (attack.weaponSubtype === 'axe') return Math.max(1, Math.floor(attack.damage * 0.5));
    }
    return attack.canSmash ? attack.damage * 2 : attack.damage;
  }

  // Whether a melee swing may damage this background object at all — the
  // companion question to resolveSmashDamage's "how much", and the reason both
  // live here rather than inline in CombatSystem's melee loop. These are the
  // materials that answer to a specific tool: obsidian, rock, boulder, tree.
  //
  // Returns null when the swing lands. Otherwise a refusal, which the caller
  // turns into feedback — `fireBypass` marks the single refusal fire can talk
  // its way past, since a Tree burns even though it will not chop.
  //
  // Order matters and mirrors what shipped: obsidian is checked before
  // allWeaponsDamage because an unbreakable rock stays unbreakable, and
  // allWeaponsDamage exempts the rock gate ONLY — the Centipede arena flags its
  // obstacle rocks so no loadout can strand the player, and that escape hatch
  // was never extended to boulders or trees.
  resolveSmashRefusal(attack, obj) {
    if (obj.obsidian) return SMASH_REFUSED;

    // Rock yields to anything that hits rather than cuts: the pickaxe, a hammer
    // (canSmash), or any blunt weapon — flail, staff, bat, baton. Blades and
    // axes clink off. Hammers carry canSmash but not isBlunt, so both flags are
    // load-bearing here.
    if (obj.char === '0') {
      const strikes = attack.isPickaxe || attack.canSmash || attack.isBlunt || obj.allWeaponsDamage;
      return strikes ? null : SMASH_REFUSED;
    }

    // A boulder wants the pickaxe or a level 2+ hammer; a level 1 hammer is not
    // enough mass.
    if (obj.char === 'Q') {
      const strikes = attack.isPickaxe || (attack.canSmash && attack.weaponLevel >= 2);
      return strikes ? null : SMASH_REFUSED;
    }

    // Trees only fall to axes — blades, hammers, and the pickaxe (rock is its
    // specialty) thunk off. Petrified Trees share the 'Y' char precisely so
    // they inherit this gate; they simply refuse the fire bypass by declaring
    // `flammability: 'none'`.
    if (obj.char === 'Y' && attack.weaponSubtype !== 'axe') return SMASH_REFUSED_UNLESS_BURNED;

    // Barricade ice answers to heat and nothing else — a Torch, a flame or lava
    // sword, the Ruby Whip, or any blade an Oil augment is burning on. Note
    // this is not the fire *bypass* the Tree above uses: that route ignites a
    // refusal, and ice does not catch fire. A burning swing is simply not
    // refused here, so the ordinary damage path melts a block the way any
    // weapon breaks any other material.
    if (obj.typeId === 'barricade_ice') {
      return attack.onHit === 'burn' ? null : SMASH_REFUSED;
    }

    return null;
  }

  // Vault (V room), shared plumbing — K room retired 2026-09-20, each zone
  // now guards its Vault a different way (RoomGenerator's
  // VAULT_UNLOCK_BY_ZONE): green/gray use a held key (this file's
  // canUnlockVault/unlockVault), red breaks the wall on contact
  // (tryBreakVaultWall, called from BoulderSystem/ExplosionEffects/
  // CombatSystem's roll-damage), cyan uses a buried switch
  // (canActivateVaultSwitch/activateVaultSwitch), yellow has no unlock path
  // at all (only Yellow Mage's blink, which ignores collisionMap, gets in).

  // True when the player stands south of the vault's bottom wall, roughly
  // centered — the shared proximity check for the key and switch paths.
  _isPlayerSouthCentered(vault) {
    const game = this.game;
    const playerGridX = Math.floor(game.player.position.x / GRID.CELL_SIZE);
    const playerGridY = Math.floor(game.player.position.y / GRID.CELL_SIZE);

    const isSouthOfVault = playerGridY > vault.bottomWallRow;
    const distanceToCenter = Math.abs(playerGridX - vault.centerCol);
    const maxCenterDist = vault.size / 2 + 2; // Lenient horizontal range
    return isSouthOfVault && distanceToCenter <= maxCenterDist;
  }

  // Clear the bottom wall, mark the vault unlocked, debris burst. Shared by
  // every unlock method — key, break, and switch all end here.
  _openVaultWall(vault) {
    const game = this.game;
    const bottomRow = vault.bottomWallRow;
    for (let col = vault.minCol; col <= vault.maxCol; col++) {
      game.currentRoom.collisionMap[bottomRow][col] = false;
    }
    vault.unlocked = true;
    game.renderer.markBackgroundDirty();

    // Visual feedback - create some debris particles
    const centerX = vault.centerCol * GRID.CELL_SIZE + (GRID.CELL_SIZE / 2);
    const bottomY = bottomRow * GRID.CELL_SIZE + (GRID.CELL_SIZE / 2);

    for (let i = 0; i < 10; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 50 + Math.random() * 50;
      const particle = new Particle(
        centerX,
        bottomY,
        '#',                    // char
        '#888888',              // color
        {                       // velocity
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed
        },
        0.8                     // lifetime
      );
      game.particles.push(tagInteriorPlane(game, particle));
    }
  }

  // Green/gray: true when the player stands south of the vault's bottom
  // wall, roughly centered, with the zone's key held.
  canUnlockVault() {
    const game = this.game;
    // Only check in EXPLORE mode with a current room and vault
    const state = game.stateMachine.getCurrentState();
    if (state !== GAME_STATES.EXPLORE || !game.currentRoom || !game.currentRoom.vaultInfo) {
      return false;
    }

    const vault = game.currentRoom.vaultInfo;

    if (vault.unlockMethod !== 'key') return false;
    if (vault.unlocked) return false;

    // Held, not equipped — the vault key is a real Item in
    // InventorySystem.keyItemInventory, granted when the key-dropping
    // object is destroyed and picked up (handleObjectEffect's dropsKey
    // branch), spent by unlockVault() below.
    if (!game.inventorySystem.hasKeyItem(vault.keyChar, game)) {
      return false;
    }

    return this._isPlayerSouthCentered(vault);
  }

  // Open the vault: clear the bottom wall, consume the key, debris burst.
  unlockVault() {
    const game = this.game;
    const vault = game.currentRoom.vaultInfo;
    if (!vault || vault.unlockMethod !== 'key' || vault.unlocked) return;

    this._openVaultWall(vault);

    // Spend the held key item (held, not equipped — no quick slot involved)
    game.inventorySystem.consumeKeyItem(vault.keyChar);
    game.audioSystem?.playSFX?.('vault_key_use');
  }

  // Red zone: a boulder, bomb, or the Red Warrior's damage roll breaks the
  // wall on contact instead of a key. `x`/`y`/`radius` are pixel-space —
  // callers pass whatever impact/hitbox/explosion footprint they already
  // have. Returns true if this call actually broke the wall.
  tryBreakVaultWall(x, y, radius = GRID.CELL_SIZE / 2) {
    const game = this.game;
    const vault = game.currentRoom?.vaultInfo;
    if (!vault || vault.unlockMethod !== 'break' || vault.unlocked) return false;

    const bottomWallY = vault.bottomWallRow * GRID.CELL_SIZE + GRID.CELL_SIZE / 2;
    const minX = vault.minCol * GRID.CELL_SIZE;
    const maxX = (vault.maxCol + 1) * GRID.CELL_SIZE;
    const halfCell = GRID.CELL_SIZE / 2;

    if (Math.abs(y - bottomWallY) > halfCell + radius) return false;
    if (x + radius < minX || x - radius > maxX) return false;

    this._openVaultWall(vault);
    game.audioSystem?.playSFX?.('vault_wall_break');
    return true;
  }

  // Cyan zone: true when the buried switch has been uncovered (walked onto
  // — PhysicsSystem's deep-snow compaction, same mechanic as any other snow
  // field) and the player is back at the vault to throw it.
  canActivateVaultSwitch() {
    const game = this.game;
    const state = game.stateMachine.getCurrentState();
    if (state !== GAME_STATES.EXPLORE || !game.currentRoom || !game.currentRoom.vaultInfo) {
      return false;
    }

    const vault = game.currentRoom.vaultInfo;
    if (vault.unlockMethod !== 'switch') return false;
    if (vault.unlocked) return false;
    if (!vault.switchObject?.compacted) return false;

    return this._isPlayerSouthCentered(vault);
  }

  activateVaultSwitch() {
    const game = this.game;
    const vault = game.currentRoom.vaultInfo;
    if (!vault || vault.unlockMethod !== 'switch' || vault.unlocked) return;

    this._openVaultWall(vault);
    game.audioSystem?.playSFX?.('vault_switch');
  }

  // Artifact ⚜ → wise fellow: consume the artifact, unlock the rare-tier hint
  // for the current zone. Returns true if a wise fellow in range took it.
  tryGiveArtifactToWiseFellow(npcArray) {
    const game = this.game;
    if (!npcArray) return false;
    for (const npc of npcArray) {
      if (!(npc instanceof WiseFellow)) continue;
      const dist = Math.hypot(
        game.player.position.x - npc.position.x,
        game.player.position.y - npc.position.y
      );
      if (dist > GRID.CELL_SIZE * 2) continue;
      if (!game.removeIngredient('⚜')) continue;
      npc.unlockRareHint(game.currentRoom?.zone || 'green', game.unlockedRareSayings);
      return true;
    }
    return false;
  }

  // Check lava tiles adjacent to water tiles and solidify them
  update(deltaTime, backgroundObjects) {
    // ── Player shockwave — runs every frame (creation handled in main.js) ────
    const sw = this.game.playerShockwave;
    if (sw) {
      sw.prevRadius = sw.radius;
      sw.radius += sw.speed * deltaTime;

      const playerPlane = planeOf(this.game.player);

      // Shake any background object the ring sweeps past (only on player's plane).
      for (const obj of backgroundObjects) {
        if (obj.destroyed) continue;
        if (!objectOnPlane(obj, playerPlane)) continue;
        const cx = obj.position.x + GRID.CELL_SIZE / 2;
        const cy = obj.position.y + GRID.CELL_SIZE / 2;
        const dist = Math.hypot(cx - sw.x, cy - sw.y);
        if (dist > sw.prevRadius && dist <= sw.radius) {
          obj._playAnimation?.('shake');
        }
      }

      // Knock back enemies the ring sweeps past (only on player's plane).
      for (const enemy of this.game._activeEnemies()) {
        if (enemy.hp <= 0) continue;
        if (!inSamePlane(this.game.player, enemy)) continue;
        const cx = enemy.position.x + GRID.CELL_SIZE / 2;
        const cy = enemy.position.y + GRID.CELL_SIZE / 2;
        const dist = Math.hypot(cx - sw.x, cy - sw.y);
        if (dist > sw.prevRadius && dist <= sw.radius) {
          this.game.physicsSystem.applyKnockback(enemy, sw.x, sw.y, 320, 0.18);
        }
      }

      if (sw.radius >= sw.maxRadius) {
        this.game.playerShockwave = null;
      }
    }

    // ── Lava/water solidification (throttled) ────────────────────────────────
    this._lavaWaterCheckTimer -= deltaTime;
    if (this._lavaWaterCheckTimer > 0) return;
    this._lavaWaterCheckTimer = 0.5;

    const combatSystem = this.game.combatSystem;
    const adjacentDist = GRID.CELL_SIZE * 1.5;

    for (const lava of backgroundObjects) {
      if (!lava.isLava || !lava.isLava()) continue;
      let solidified = false;
      for (const other of backgroundObjects) {
        if (other === lava || other.destroyed) continue;
        const dx = lava.position.x - other.position.x;
        const dy = lava.position.y - other.position.y;
        if (dx * dx + dy * dy > adjacentDist * adjacentDist) continue;

        const isWaterTile = (other.isWater && other.isWater()) || other.char === '=';
        if (isWaterTile) {
          lava.solidifyToRock();
          combatSystem.newSteamClouds.push({
            x: lava.position.x + GRID.CELL_SIZE / 2,
            y: lava.position.y + GRID.CELL_SIZE / 2,
            radius: GRID.CELL_SIZE * 2,
            timer: 3.0
          });
          solidified = true;
          break;
        }

        // Lava burns flammable neighbors. Rock/wall/metal (flammability 'none')
        // and other lava are immune.
        if (other.isLava && other.isLava()) continue;
        if (other.isFlammable && other.isFlammable() && !other.onFire) {
          other.ignite(other.data?.burnDuration || 2.0);
        }
      }
      if (solidified) continue;
    }
  }

  findNearbyBackgroundObject() {
    const game = this.game;
    // When inside a hut/dungeon/maze, search the appropriate objects.
    // Maze stays suppressed by design (MazeSystem owns its objects, #107).
    const objects = (game.player?.inMaze && game.mazeInterior)
      ? []
      : game._activeBackgroundObjects();
    const playerPlane = planeOf(game.player);
    for (const obj of objects) {
      if (!objectOnPlane(obj, playerPlane)) continue;
      // Cut grass (',') is inert decoration with no spacebar interaction of
      // its own — it must not intercept the scan ahead of a real
      // interactable (e.g. a revealed Sinkhole '⬤' sitting among its
      // now-cut neighbor tiles). Uncut grass ('|') is left alone: it's
      // meant to hide what's underneath until cut.
      if (obj.char === ',') continue;
      const distance = game.physicsSystem.getDistance(game.player, obj);
      if (distance < INTERACTION_RANGE) {
        return obj;
      }
    }
    return null;
  }

  // Fairy touch resolution. Called per-frame from main.js for each Fairy in
  // neutralCharacters. Returns true if the fairy was consumed by the touch,
  // so the caller can despawn it.
  //
  // Touch is now the heal outcome only — catching a fairy in an Empty Bottle
  // is the armed-slot SPACE action instead (tryBottleFairy below). While a
  // Bottle is armed, touch resolution stands down entirely: a player closing
  // in on a fairy with the bottle out is hunting it, and letting the walk-up
  // spend the fairy on a heal made the catch unwinnable.
  //
  // Only fires while the fairy is in 'flutter' state. Fleeing/dusting/
  // delivering fairies don't react to touch.
  // Shared by Game.updateExploreState and Game.updateNeutralState — handles
  // Leshy (chase-start on reaching an exit) and Fairy (bottle-catch via
  // checkFairyTouch) neutral characters. The Leshy branch is a no-op in
  // NEUTRAL state since no Leshy is ever pushed into neutralCharacters there.
  updateNeutralCharacters(deltaTime) {
    const game = this.game;
    for (let i = game.neutralCharacters.length - 1; i >= 0; i--) {
      const char = game.neutralCharacters[i];
      char.update(deltaTime, game);

      if (char instanceof Leshy && char.reachedExit) {
        const exitDirection = char.targetExit;
        if (game.currentRoom.exits[exitDirection]) {
          if (typeof game.currentRoom.exits[exitDirection] === 'object') {
            game.currentRoom.exits[exitDirection].chaseEvent = true;
          } else {
            game.currentRoom.exits[exitDirection] = {
              chaseEvent: true,
              letter: game.currentRoom.exits[exitDirection].letter || '?',
              color: game.currentRoom.exits[exitDirection].color || '#00ff00'
            };
          }
          game.zoneSystem.startLeshyChase(exitDirection);
        }
        game.neutralCharacters.splice(i, 1);
        continue;
      }

      if (char instanceof Fairy) {
        this.checkFairyTouch?.(char);
        if (char.consumed || char.state === 'exited') {
          game.neutralCharacters.splice(i, 1);
          continue;
        }
      }
    }
  }

  checkFairyTouch(fairy) {
    const game = this.game;
    const player = game.player;
    if (!player || !fairy) return false;
    if (fairy.state !== 'flutter') return false;
    if (fairy.consumed) return false;
    // Spawn-grace: ignore touches for the first ~2s so the player can see the
    // fairy before incidentally consuming it.
    if ((fairy.touchImmunityTimer ?? 0) > 0) return false;

    // AABB overlap between player hitbox and fairy hitbox
    const fh = fairy.getHitbox();
    const px = player.position.x;
    const py = player.position.y;
    const pw = player.width  ?? GRID.CELL_SIZE;
    const ph = player.height ?? GRID.CELL_SIZE;
    if (px + pw < fh.x || px > fh.x + fh.width)  return false;
    if (py + ph < fh.y || py > fh.y + fh.height) return false;

    // An armed Empty Bottle claims the fairy for tryBottleFairy — see header.
    if (this._armedBottleIndex() >= 0) return false;

    // At full health, touch does nothing — the fairy is worth more than a
    // no-op heal. tryFairyBlessing (SPACE, below) is the deliberate gesture
    // for a full-health player instead.
    if (player.hp >= player.maxHp) return false;

    // Full heal. No text — the HP readout blinks instead.
    player.hp = player.maxHp;
    game.audioSystem?.playSFX?.('fairy_pickup');
    game.menuSystem?.updateUI?.();
    this._blinkHPDisplay();
    fairy.consume();
    return true;
  }

  /** Index of the armed (number-key selected) Empty Bottle slot, or -1. */
  _armedBottleIndex() {
    const idx = this.game.player?.selectedConsumableIndex ?? -1;
    if (idx < 0) return -1;
    return this.game.player.equippedConsumables?.[idx]?.char === 'B' ? idx : -1;
  }

  /**
   * SPACE with the Bottle slot armed and a catchable fairy within reach →
   * the slot becomes a Fairy in a Bottle (⚱). Deliberately the same gesture
   * as filling a bottle from mud/lava/water (AlchemySystem.tryFillArmedBottle):
   * arm the bottle, stand next to the thing you want in it, press SPACE. Like
   * that path it must be checked ahead of ConsumableTriggerSystem.fireSelected(),
   * which would otherwise swallow the press on an Empty Bottle's absent effect.
   *
   * No HP condition — the catch is a deliberate act, so a wounded player is
   * free to bank the fairy instead of spending it on a heal.
   */
  tryBottleFairy() {
    const game = this.game;
    const slotIndex = this._armedBottleIndex();
    if (slotIndex < 0) return false;

    const fairy = this._nearestCatchableFairy();
    if (!fairy) return false;

    const inv = game.inventorySystem;
    if (!inv?.replaceConsumableSlot?.(slotIndex, '⚱')) {
      this._fallbackReplaceConsumableSlot(slotIndex, '⚱');
    }
    game.player.selectedConsumableIndex = -1;
    game.menuSystem?.showPickupMessage?.('CAUGHT A FAIRY!');
    game.audioSystem?.playSFX?.('fairy_pickup');
    game.menuSystem?.updateUI?.();
    fairy.consume();
    return true;
  }

  /**
   * SPACE with no Bottle armed, next to a fairy, at full health — permanent
   * +1 max HP. Counterpart to checkFairyTouch's walk-up heal: touch stands
   * down once the player is topped off (see the gate there), so this is the
   * deliberate gesture that makes a full-health encounter worth something
   * instead of the fairy just going to waste.
   */
  tryFairyBlessing() {
    const game = this.game;
    const player = game.player;
    if (!player || player.hp < player.maxHp) return false;
    if (this._armedBottleIndex() >= 0) return false;

    const fairy = this._nearestCatchableFairy();
    if (!fairy) return false;

    player.maxHp += 1;
    player.hp = player.maxHp;
    game.audioSystem?.playSFX?.('fairy_pickup');
    game.menuSystem?.showPickupMessage?.('+1 MAX HP');
    game.menuSystem?.updateUI?.();
    this._blinkHPDisplay();
    fairy.consume();
    return true;
  }

  /**
   * Nearest fairy within FAIRY_CATCH_RADIUS that is willing to be caught.
   * 'flutter' and 'ambient' both qualify — a fountain room's ambient fairies
   * are as real as a fairy-grass one, and the old touch path could never
   * reach them. A fairy already fleeing, dusting, delivering or carrying is
   * mid-errand and stays out of reach.
   */
  _nearestCatchableFairy() {
    const CATCHABLE = new Set(['flutter', 'ambient']);
    const player = this.game.player;
    if (!player) return null;
    const px = player.position.x + (player.width ?? GRID.CELL_SIZE) / 2;
    const py = player.position.y + (player.height ?? GRID.CELL_SIZE) / 2;

    let best = null;
    let bestDist = FAIRY_CATCH_RADIUS;
    for (const char of this.game.neutralCharacters || []) {
      if (!(char instanceof Fairy) || char.consumed) continue;
      if (!CATCHABLE.has(char.state)) continue;
      const dist = Math.hypot(px - char.position.x, py - char.position.y);
      if (dist < bestDist) {
        bestDist = dist;
        best = char;
      }
    }
    return best;
  }

  // Retrigger the HP heal-blink CSS animation by toggling the class off/on.
  _blinkHPDisplay() {
    const el = document.getElementById('hp-display');
    if (!el) return;
    el.classList.remove('heal-blink');
    // Force reflow so removing+re-adding restarts the animation.
    void el.offsetWidth;
    el.classList.add('heal-blink');
  }

  // Fallback when InventorySystem doesn't expose a slot-replace helper. Writes
  // a minimal item-like wrapper directly into both inventory and player slots.
  _fallbackReplaceConsumableSlot(slotIndex, newChar) {
    const game = this.game;
    const newItem = new Item(newChar, 0, 0);
    const inv = game.inventorySystem;
    if (inv?.equippedConsumables) {
      inv.equippedConsumables[slotIndex] = newItem;
    }
    if (game.player?.equippedConsumables) {
      game.player.equippedConsumables[slotIndex] = newItem;
    }
  }

  // Spacebar-triggered container open: bypasses HP/damage and runs the
  // object's dropEffect directly. Used for barrels, crates, metal boxes —
  // any object whose acceptsInteractions includes 'spacebar' or 'all'.
  openContainer(obj) {
    if (!obj || obj.destroyed || obj.destroyAfterAnimation) return;
    const effect = obj.data.dropEffect;
    if (!effect) return;

    if (obj.originalChar === 'T') {
      // Tomb is a stateful container — glyph flips closed→open in place via
      // openTomb() instead of the shared destroy/'crack' path every other
      // container takes. It is never destroyed, so it's exempt from the
      // destroyAfterAnimation branch below.
      obj.openTomb();
    } else {
      obj.destroyAfterAnimation = true;
      obj._playAnimation('crack');
    }
    this.handleObjectEffect(effect, obj);
    this.game.renderer.markBackgroundDirty();
  }

  interactWithObject(obj) {
    const game = this.game;
    const heldItemChar = game.player.heldItem ? game.player.heldItem.char : null;

    // Fountain water is its own liquid family — fairy water when the pool is
    // unattuned, the matching elemental bottle once a gem has coloured it.
    // Checked before the generic liquid path, which would otherwise read the
    // pool as ordinary water and hand back a plain 🜉 bottle.
    if (game.fountainSystem.tryBottleFountainWater(obj)) return;

    const result = obj.interact(heldItemChar);

    // Leshy spawn event: trigger on ANY interaction with shaking bush (not just destruction)
    if (obj.leshyBush && !obj.leshySpawned) {
      obj.leshySpawned = true; // Mark to prevent multiple spawns
      const leshy = new Leshy(obj.position.x, obj.position.y, game.currentRoom.exits);
      leshy.startFleeing();
      game.neutralCharacters.push(leshy);
      game.zoneSystem.startLeshyChase(leshy.targetExit);
      console.log(`[Secret] Leshy discovered! Fleeing to ${leshy.targetExit} exit`);
    }

    if (result.effect) {
      this.handleObjectEffect(result.effect, obj);
    }

    if (result.message) {
      console.log(result.message);
    }
  }

  handleObjectEffect(effect, obj, attack = null) {
    const game = this.game;
    if (!effect) return;

    // Key items (green Vault's Vault Key, dungeon Skull Key): destroying the
    // carrying object spawns a real, pickup-able Item — held like any
    // weapon/armor drop, just routed by InventorySystem.tryPickupItem's KEY
    // branch into keyItemInventory instead of a quick/equip slot, so it
    // never occupies a loadout slot. See canUnlockVault/unlockVault and
    // DungeonPuzzleSystem's Key Vault gate, which read hasKeyItem/
    // consumeKeyItem — the pickup sfx plays once it's actually held
    // (main.js's tryPickupItem wrapper), not here at mere destruction.
    if ((obj.dropsKey || obj.dropsDungeonKey) && effect.includes('destroyObject')) {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      game.lootSystem.spawnItemDrop(obj.keyChar, obj.position.x, obj.position.y, null, obj);
      return;
    }

    // Rock harvest is checked BEFORE generic dropTable so mineral-formation rocks
    // (which have dropTable='basic' set by RoomGenerator) still get the guaranteed
    // Rock drop. Zone dropTable extras stack on top of the harvest rolls.
    if (effect === 'destroyObject:rockHarvest') {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      // Guaranteed Rock + a ~15% Ore + a ~7% zone mineral (each zone's rocks
      // hide a different rare: knowledge of WHERE to smash rocks is the gate)
      // + 3% Artifact. Red zone runs the richer vein everywhere (it owns
      // Metal, Ore's whole reason to exist), and any Underground room
      // compounds that further — red Underground doubly so, every other
      // zone's Underground gets a smaller version of the same bump so a U
      // room is always worth a detour, not just red's.
      const zone = game.currentRoom?.zone;
      const isUnderground = !!game.currentRoom?.underground;
      const mineralMult = (zone === 'red' ? 2 : 1) * (isUnderground ? (zone === 'red' ? 1.5 : 1.25) : 1);
      const rolls = [
        { char: '0', chance: 0.50 },
        { char: '2', chance: 0.15 * mineralMult }, // Ore
        { char: '⚜', chance: 0.03 }
      ];
      const zoneMineral = this.getZoneMineral(zone);
      if (zoneMineral) rolls.splice(1, 0, { char: zoneMineral, chance: 0.07 * mineralMult });
      let i = 0;
      for (const r of rolls) {
        if (Math.random() < r.chance) {
          const angle = (i / rolls.length) * Math.PI * 2 + Math.random() * 0.4;
          if (isIngredient(r.char)) {
            game.lootSystem.spawnIngredientDrop(r.char, obj.position.x, obj.position.y, angle, obj);
          } else {
            game.lootSystem.spawnItemDrop(r.char, obj.position.x, obj.position.y, angle, obj);
          }
          i++;
        }
      }
      // Zone-formation rocks also roll their dropTable bonus (e.g. red-zone gemstones).
      if (obj.dropTable) {
        const rarityProfile = obj.dropTable === 'rare_gemstone' ? 'elite' : 'normal';
        const extras = generateEnemyDrops(obj.dropTable, rarityProfile, 1);
        for (const drop of extras) {
          if (isIngredient(drop)) {
            const angle = Math.random() * Math.PI * 2;
            game.lootSystem.spawnIngredientDrop(drop, obj.position.x, obj.position.y, angle, obj);
          }
        }
      }
      return;
    }

    // Check for zone-specific drop tables (e.g., gemstones from RED zone rocks)
    if (obj.dropTable && effect.includes('destroyObject')) {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();

      const rarityProfile = obj.dropTable === 'rare_gemstone' ? 'elite' : 'normal';
      const drops = generateEnemyDrops(obj.dropTable, rarityProfile, 1);

      for (const drop of drops) {
        if (isIngredient(drop)) {
          game.lootSystem.spawnIngredientDrop(drop, obj.position.x, obj.position.y, null, obj);
        }
      }
      return;
    }

    // Handle destroy + spawn combined effects
    if (effect.startsWith('destroyObject:spawnIngredient:')) {
      let ingredientChar = effect.split(':')[2];

      // Quagmire decor drops "1st ingredients" (any starter-potion ingredient)
      // instead of its typical per-object drop — the room is an alchemy
      // ingredient source before it's anything else.
      if (game.currentRoom?.letterTemplate?.quagmire && isIngredient(ingredientChar)) {
        ingredientChar = pickQuagmireIngredient();
      }

      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      // Not always an ingredient char — e.g. the caldera Ember Bush drops the
      // Unicode/CONSUMABLE Fire Berry, which needs the Item pickup pipeline.
      if (isIngredient(ingredientChar)) {
        game.lootSystem.spawnIngredientDrop(ingredientChar, obj.position.x, obj.position.y, null, obj);
      } else {
        game.lootSystem.spawnItemDrop(ingredientChar, obj.position.x, obj.position.y, null, obj);
      }

      // Tree harvest mirrors rockHarvest: guaranteed Stick above, plus a 15%
      // sap bonus (red/cyan zones carry rare elemental saps; others common ŝ).
      if (obj.originalChar === 'Y' && Math.random() < 0.15) {
        const zone = game.currentRoom?.zone;
        const sapChar = zone === 'red' ? 'š' : zone === 'cyan' ? 'ş' : 'ŝ';
        const angle = Math.random() * Math.PI * 2;
        game.lootSystem.spawnIngredientDrop(sapChar, obj.position.x, obj.position.y, angle, obj);
      }
    } else if (effect === 'destroyObject:spawnRandom') {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();

      // Barrels are provisions caches: 25% of non-empty barrels yield a bread
      // loaf instead of a generic roll (hut floor-spawn rate was cut in favor
      // of this path). Crates/metal boxes share spawnRandom and are unaffected.
      if (obj.originalChar === 'p' && Math.random() < 0.25) {
        game.lootSystem.spawnItemDrop('⌬', obj.position.x, obj.position.y, null, obj);
      } else {
        const drops = generateEnemyDrops('generic', 'weak', 1);
        for (const drop of drops) {
          if (isIngredient(drop)) {
            game.lootSystem.spawnIngredientDrop(drop, obj.position.x, obj.position.y, null, obj);
          } else if (isItem(drop)) {
            game.lootSystem.spawnItemDrop(drop, obj.position.x, obj.position.y, null, obj);
          }
        }
      }
    } else if (effect === 'destroyObject:spawnChestLoot') {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      game.audioSystem?.playSFX('chest_open');

      const drops = generateEnemyDrops('generic', 'normal', 2);
      for (const drop of drops) {
        if (isIngredient(drop)) {
          game.lootSystem.spawnIngredientDrop(drop, obj.position.x, obj.position.y, null, obj);
        } else if (isItem(drop)) {
          game.lootSystem.spawnItemDrop(drop, obj.position.x, obj.position.y, null, obj);
        }
      }
      // Rare Artifact roll on chests — separate from generic loot pool so it
      // doesn't leak into barrels/crates (which share `generic`). 10% per chest.
      if (Math.random() < 0.10) {
        game.lootSystem.spawnIngredientDrop('⚜', obj.position.x, obj.position.y, null, obj);
      }
    } else if (effect === 'openTomb') {
      // Two independent rolls, neither/either/both can land — the object
      // itself was already state-swapped to 't' (Open Tomb) by openContainer()
      // calling BackgroundObject.openTomb() before this ran, and is never
      // destroyed here.
      if (Math.random() < 0.5) {
        const drops = generateEnemyDrops('generic', 'normal', 1);
        for (const drop of drops) {
          if (isIngredient(drop)) {
            game.lootSystem.spawnIngredientDrop(drop, obj.position.x, obj.position.y, null, obj);
          } else if (isItem(drop)) {
            game.lootSystem.spawnItemDrop(drop, obj.position.x, obj.position.y, null, obj);
          }
        }
      }
      if (Math.random() < 0.3 && game.activeFloor) {
        game.dungeonGhostSystem.spawnAt(game.activeFloor, obj.position.x, obj.position.y);
      }
    } else if (effect === 'destroyObject') {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
    } else if (effect === 'sinkholeDive') {
      game.sinkholeSystem?.dive(game.currentRoom, obj.sinkholeRef);
    } else if (effect === 'cutGrass') {
      // Frozen grass (tinted by a Freeze Trap) emits an ice burst when sliced.
      if (obj.frozen) {
        for (const p of createIceBurst(
          obj.position.x + GRID.CELL_SIZE / 2,
          obj.position.y + GRID.CELL_SIZE / 2
        )) game.particles.push(tagInteriorPlane(game, p));
      }
      // Grass drop table — rolled independently per grass object cut.
      // Thresholds are 1/8 of the per-swing values so that ~8 blades per swing
      // yields the same expected drop rate as before.
      {
        const roll = Math.random();
        if (roll < 0.0006) {
          // Very rare: chest
          const chest = new BackgroundObject('⊞', obj.position.x, obj.position.y);
          chest.spawnImmunityTimer = 1.0;
          game._activeBackgroundObjects().push(chest);
          game.renderer.markBackgroundDirty();
        } else if (roll < 0.0013) {
          // Very rare: coin
          game.lootSystem.spawnIngredientDrop('c', obj.position.x, obj.position.y, null, obj);
        } else if (roll < 0.004345) {
          // Uncommon: beast lurking in the grass. The band is 0.003045 wide —
          // baseline, cut 30%, then halved again — and every threshold below it
          // is shifted down by that same halving, so only the beast rate moved
          // and the stick/rock/pollen/axe-head/arrowhead bands keep their width.
          // Fully respects the zone's normal depth-gated spawn table — no
          // separate/guaranteed roll. If the roll happens to land on Goblin,
          // it carries a Scythe (the item's sole source, since Goblin no
          // longer drops it as a ground spawn).
          if (game._activeEnemies().length < 10) {
            const beastChar = getZoneRandomEnemy(game.getCurrentZoneDepth(), game.currentRoom?.zone);
            const dataOverride = beastChar === 'G'
              ? { ...ENEMIES['G'], spawnEquipment: { chance: 1.0, weapons: ['Ƨ'] } }
              : undefined;
            const spawned = game.roomGenerator.spawnEnemiesFrom(game, obj, {
              spawnChar: beastChar,
              spawnCount: 1,
              spawnRange: GRID.CELL_SIZE * 2,
              spawnerPosition: { x: obj.position.x, y: obj.position.y },
              dataOverride
            });
            game._activeEnemies().push(...spawned);
          }
        } else if (roll < 0.008745) {
          // Uncommon: stick
          game.lootSystem.spawnIngredientDrop('|', obj.position.x, obj.position.y, null, obj);
        } else if (roll < 0.013145) {
          // Uncommon: rock
          game.lootSystem.spawnIngredientDrop('0', obj.position.x, obj.position.y, null, obj);
        } else if (roll < 0.016245) {
          // Uncommon: pollen (raw oil)
          game.lootSystem.spawnIngredientDrop('ł', obj.position.x, obj.position.y, null, obj);
        } else if (roll < 0.016745) {
          // Rare: axe head
          game.lootSystem.spawnIngredientDrop('⊿', obj.position.x, obj.position.y, null, obj);
        } else if (roll < 0.017245) {
          // Rare: arrowhead
          game.lootSystem.spawnIngredientDrop('△', obj.position.x, obj.position.y, null, obj);
        }
      }
      // χ grass: blade-cut reveals the mysterious χ. Singular per room — only
      // one tile is ever marked (RoomGenerator's chi_grass secret event).
      // The marker is puzzleSignal (never destroyed by strikes); ChiBladeSystem
      // polls its glitterHit pulse and resolves the χ-blade reveal.
      if (obj.chiGrass && !game.currentRoom?.chiRevealed) {
        game.currentRoom.chiRevealed = true;
        const chi = new BackgroundObject('χ', obj.position.x, obj.position.y);
        chi.spawnImmunityTimer = 1.0;
        chi.puzzleSignal = true;
        game._activeBackgroundObjects().push(chi);
        game.renderer.markBackgroundDirty();
      }
      // Barricade grass: a trigger fixture concealed under this tile. The cut
      // is the whole reveal — same shape as the χ grass above, asked as a gate.
      if (obj.barricadeTrigger) {
        game.barricadeSystem.revealTrigger(obj);
      }
      // Fairy grass: blade-cut releases the fairy. Multiple grass tiles in the
      // room are marked; the first one cut spawns the fairy, the rest are inert.
      if (obj.fairyGrass && !game.currentRoom?.fairySpawned && !game.fairiesAngered) {
        game.currentRoom.fairySpawned = true;
        const fairy = new Fairy(
          obj.position.x + GRID.CELL_SIZE / 2,
          obj.position.y + GRID.CELL_SIZE / 2,
          game.currentRoom.exits
        );
        game.neutralCharacters.push(fairy);
        console.log('[Secret] Fairy discovered!');
      }
      // Sinkhole reveal: majority of the grass tiles touching a concealed
      // Sinkhole must be cut before it surfaces as a ⬤ glyph.
      const sinkholes = game.currentRoom?.sinkholes;
      if (sinkholes?.length) {
        for (const sink of sinkholes) {
          if (sink.revealed) continue;
          if (!sink.adjacentGrass.includes(obj)) continue;
          sink.cutSet.add(obj);
          if (sink.cutSet.size / sink.adjacentGrass.length > 0.5) {
            game.sinkholeSystem?.reveal(sink);
          }
        }
      }
    } else if (effect === 'destroyObject:spawnGemstone') {
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      // Always drop 1-2 regular stones (building material for bridge quest).
      const stoneCount = Math.random() < 0.5 ? 2 : 1;
      for (let i = 0; i < stoneCount; i++) {
        const angle = (i / stoneCount) * Math.PI * 2 + Math.random() * 0.5;
        game.lootSystem.spawnIngredientDrop('0', obj.position.x, obj.position.y, angle, obj);
      }
      // Gem drop: 75% chance per rock until the room's minimum is met, and the
      // remaining rocks force the rest if the rolls come up short — an
      // Underground visit is the mining trip, so it pays out at least
      // MIN_GEMS_PER_ROOM even on a cold streak. Past the minimum the rolls
      // keep going, so a rich seam can hand back more than two.
      // Ore and Metal ride in the same vein pool as the gems — every zone's
      // Underground room can turn one up, but red (Metal's home zone) gets
      // them at double weight so its veins read richer, same as the rockHarvest bump above.
      const GEM_CHARS = ['◇', '⬥', '⬦', '⧫', '⬧', '◈', '⬨'];
      const veinChars = game.currentRoom?.zone === 'red'
        ? [...GEM_CHARS, '2', '2', 'M', 'M']
        : [...GEM_CHARS, '2', 'M'];
      const GEM_CHANCE = 0.45;
      const MIN_GEMS_PER_ROOM = 2;
      const gemsSoFar = game.currentRoom.miningGemsDropped || 0;
      const rocksRemaining = game._activeBackgroundObjects().filter(
        o => !o.destroyed && o.data?.glitteringRock && o !== obj
      ).length;
      // Rocks left after this one have to cover whatever the minimum still
      // needs; when they can't, this rock is one of the guaranteed drops.
      const shortfall = MIN_GEMS_PER_ROOM - gemsSoFar;
      if (shortfall > rocksRemaining || Math.random() < GEM_CHANCE) {
        game.currentRoom.miningGemsDropped = gemsSoFar + 1;
        const gemChar = veinChars[Math.floor(Math.random() * veinChars.length)];
        game.lootSystem.spawnIngredientDrop(gemChar, obj.position.x, obj.position.y, null, obj);
      }
    } else if (effect.startsWith('destroyObject:spawnWeapon:')) {
      const weaponChar = effect.split(':')[2];
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
      const weapon = new Item(weaponChar, obj.position.x, obj.position.y);
      game.items.push(weapon);
      game.physicsSystem.addEntity(weapon);
    } else if (effect.startsWith('spawnIngredient:')) {
      let ingredientChar = effect.split(':')[1];

      // Rock poke (bullet/staff '/' interaction): yields the zone mineral
      // instead of the data-table Metal, and only once per rock — the
      // repeatable guaranteed-Metal poke was the gun-leveling faucet.
      if (obj.char === '0' || obj.originalChar === '0') {
        if (obj.pokeMineralClaimed) return;
        obj.pokeMineralClaimed = true;
        const zoneMineral = this.getZoneMineral(game.currentRoom?.zone);
        if (!zoneMineral) return;
        ingredientChar = zoneMineral;
      }

      if (isIngredient(ingredientChar)) {
        game.lootSystem.spawnIngredientDrop(ingredientChar, obj.position.x, obj.position.y, null, obj);
      } else {
        game.lootSystem.spawnItemDrop(ingredientChar, obj.position.x, obj.position.y, null, obj);
      }
    } else if (effect.startsWith('spawnMultiple:')) {
      // Format: spawnMultiple:char:count
      const parts = effect.split(':');
      const ingredientChar = parts[1];
      const count = parseInt(parts[2]) || 2;

      for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2 + Math.random() * 0.5;
        game.lootSystem.spawnIngredientDrop(ingredientChar, obj.position.x, obj.position.y, angle, obj);
      }
    } else if (effect.startsWith('transformObject:')) {
      // Format: transformObject:newChar
      const newChar = effect.split(':')[1];

      const activeBgObjects = game._activeBackgroundObjects();
      const index = activeBgObjects.indexOf(obj);
      if (index !== -1) {
        const newObj = new BackgroundObject(newChar, obj.position.x, obj.position.y);
        activeBgObjects[index] = newObj;

        const animData = OBJECT_ANIMATIONS['freeze'] || OBJECT_ANIMATIONS['melt'];
        if (animData) {
          newObj.currentAnimation = {
            type: 'transform',
            data: animData,
            elapsed: 0
          };
        }

        game.renderer.markBackgroundDirty();
      }
    } else if (effect === 'spawnFire') {
      const fire = new BackgroundObject('!', obj.position.x, obj.position.y);
      game._activeBackgroundObjects().push(fire);
      obj.destroyAfterAnimation = true;
      game.renderer.markBackgroundDirty();
    } else if (effect.startsWith('spawnCloud:')) {
      // Format: spawnCloud:type (poison, smoke, etc.)
      const cloudType = effect.split(':')[1];
      const cloudColor = cloudType === 'poison' ? '#88ff00' : '#888888';

      for (let i = 0; i < 10; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 50 + 30;
        const particle = {
          x: obj.position.x + GRID.CELL_SIZE / 2,
          y: obj.position.y + GRID.CELL_SIZE / 2,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          life: 1.0,
          maxLife: 1.0,
          char: '·',
          color: cloudColor,
          size: 4
        };
        game.particles.push(tagInteriorPlane(game, particle));
      }
    }
  }

  checkCaptiveInteraction() {
    const game = this.game;
    if (!game.captives || game.captives.length === 0) return false;

    for (const captive of game.captives) {
      if (captive.freed) continue;

      const dist = Math.hypot(
        game.player.position.x - captive.position.x,
        game.player.position.y - captive.position.y
      );

      if (dist < INTERACTION_RANGE * 2) {
        if (!captive.cageDestroyed) {
          // First interaction: destroy the cage
          captive.cageDestroyed = true;

          const cageDebris = createDebris(
            captive.position.x,
            captive.position.y,
            12,
            '#ffaa00'
          );
          for (const piece of cageDebris) game.debris.push(tagInteriorPlane(game, piece));

          game.captiveInteractionThisFrame = true;
          return true;
        } else {
          // Second interaction: recruit the character
          captive.freed = true;
          game.unlockedCharacters.push(captive.characterType);
          const charData = CHARACTER_TYPES[captive.characterType];
          game.showPickupMessage(`${charData.name} obtained`);
          game.saveGameState();

          game.captiveInteractionThisFrame = true;
          return true;
        }
      }
    }
    return false;
  }
}
